targets.expr:
sum(
  increase(
    traefik_router_requests_total{
      ingress_namespace=~"$namespace",
      ingress_namespace!="",
      ingress=~"$ingress",
      ingress!="",
      router=~"$router",
      exported_service=~"$service"
    }[$__interval]
  )
) by (ingress_namespace)

sum(
  increase(
    traefik_router_requests_total{
      ingress_namespace=~"$namespace",
      ingress_namespace!="",
      ingress=~"$ingress",
      ingress!="",
      rule_path!="",
      router=~"$router",
      exported_service=~"$service"
    }[$__interval]
  )
) by (rule_path)

histogram_quantile(
  0.99,
  sum by (le)(
    rate(
      traefik_router_request_duration_seconds_bucket{code!="404", code!="500", code!="304", ingress_namespace=~"$namespace", ingress_namespace!="", ingress=~"$ingress", ingress!="", router=~"$router", exported_service=~"$service"}[$__interval]
    )
  )
)

